export const TransmutationsOverviewData = {
    "Name": "Transmutations",
    "Content": [
        {
            "type": "paragraph",
            "text": "Ancient alchemists sought to transmute the base matter of lead into gold. For a Promethean, the base matter she experiments upon is her own body and the “gold” she creates is a miraculous alteration of self that unlocks supernatural power. The transformation of dead flesh to living flesh at the hands of a Progenitor is only the first of these Transmutations. The Bestowments granted by the process of becoming a Promethean are perhaps the simplest sort of Transmutation, but greater power is found in those changes wrought by the Refinements."
        },
        {
            "type": "paragraph",
            "text": "Newly created Prometheans haven’t undergone very many Transmutations. Those gained during the process of character creation may represent the few changes a Promethean has discovered for herself, or they might be the legacy of a helpful or experimental creator. Because the Created is immune to the ravages of age, she may acquire any number of Transmutations before she eventually surrenders them to achieve Mortality or succumbs to time catching up with her. An old Promethean is dangerous to cross, as the mixture of Transmutations she has gained are likely to grant great flexibility in their variety and incredible potency in their effects."
        },
        {
            "type": "heading",
            "level": 2,
            "text": "Gaining Transmutations"
        },
        {
            "type": "paragraph",
            "text": "Transmutations are classified according to their core concept and are ranked by dots. These ranks do not need to be purchased in sequential order. For example, a player could purchase Alteration, a four-dot Alchemicus Transmutation, without ever having to buy any of the lower-ranked Alchemicus Transmutations. He may also purchase multiple Transmutations of the same rank (possessing two or more four-dot Alchemicus Transmutations, for example). There are, however, some Transmutations that require certain lower-ranked Transmutations as prerequisites. These exceptions are clearly marked."
        },
        {
            "type": "paragraph",
            "text": "Each Refinement specializes in two classes of Transmutations; these are their affinities. For instance, the Mercurius specialize in the Alchemicus and Vulcanus Transmutations. Prometheans who practice that Refinement can purchase these Transmutations at a lower experience point cost than other Prometheans."
        },
        {
            "type": "paragraph",
            "text": "Transmutations require great effort to achieve. There is no college dedicated to teaching Prometheans how to develop new powers. Characters need to find other Created who are willing to teach them, or they must embark on a long process of trial and error. Such efforts generally involve experimentation with alchemical processes designed to manipulate the Divine Fire. This research might range from delving into crumbling texts of forgotten would-be demiurges to performing nightmarishly grotesque surgeries."
        },
        {
            "type": "paragraph",
            "text": "Each of the Promethean Lineages inherently possesses a specific power, which the Created term a Bestowment. Rightfully these powers are just another type of Transmutation, as demonstrated by the fact that they can be achieved by other Lineages. To gain the Bestowment of another Lineage, the Created must undergo the same sort of alchemical changes that bring her a new Transmutation, and her player must pay a number of experience points. See pp. 116-117 for details of the Bestowments and their required Transmutation costs."
        },
        {
            "type": "heading",
            "level": 3,
            "text": "Transmutation Costs"
        },
        {
            "type": "table",
            "title": "Experience Point Costs",
            "headers": ["Dots", "Affinity (x5)", "Non-Affinity (x7)"],
            "rows": [
                ["•", 5, 7],
                ["••", 10, 14],
                ["•••", 15, 21],
                ["••••", 20, 28],
                ["•••••", 25, 35]
            ]
        },
        {
            "type": "paragraph",
            "text": "Transmutations do not need to be bought in sequence. A player can purchase a three-dot Transmutation for his character without first learning a one- or two-dot Transmutation. It is, however, more expensive to purchase a Transmutation thus, without having first learned a power from the previous dot ranks. The cost increases by +3 experience points per dot rank missed in the sequence. This cost for a missed dot rank applies to each subsequent purchase of a Transmutation in the same class for as long as the gap in the sequence exists."
        },
        {
            "type": "paragraph",
            "text": "Example: Conrad wants to buy the three-dot Metamorphosis Transmutation Procrustean Shape for his character, who practices the Refinement of Copper — an affinity Transmutation for him. Normally, this purchase would cost him 15 experience points, but his character knows only a one-dot Metamorphosis Transmutation (Mask of Medusa). He doesn’t know any two-dot Transmutations in that class. Conrad must pay 18 experience points, since the cost is +3 due to his lack of the intervening dot rank. If he didn’t know any one-dot Transmutations either, the cost would be 21 experience points (+3 per missing dot rank). If he knew at least one one-dot Transmutation and one two-dot Transmutation, he wouldn’t need to pay any extra cost. If Conrad had a one-dot Transmutation from the class, skipped the two-dot rank, bought a three-dot Transmutation and then wanted to buy a four-dot Transmutation, the +3 cost still applies to his purchase of the four-dot Transmutation because he’s still missing a two-dot Transmutation from that class."
        },
        {
            "type": "heading",
            "level": 2,
            "text": "Using Transmutations"
        },
        {
            "type": "paragraph",
            "text": "The basic system for using a Transmutation varies depending upon the individual power in question. Some Transmutations depend entirely upon the Promethean’s mundane Skills and talent with the Divine Fire, and therefore require a roll using the relevant Skill + Azoth to determine success. Other Transmutations are aided by the Created’s natural strengths, allowing the Promethean’s player to roll dice equal to the applicable Attribute + Skill or Attribute + Azoth. A few Transmutations, usually those that allow the victim to resist, might combine two appropriate Attributes + a Skill. (See “Extra Talent,” World of Darkness Rulebook, p. 135.) Appropriate Specialties can be applied to Skill-based Transmutation rolls."
        },
        {
            "type": "paragraph",
            "text": "Besides showing what dice pool to use, each Transmutation entry includes:"
        },
        {
            "type": "list",
            "items": [
                "Trait costs, if any, such as Pyros expenditures.",
                "Bonuses or penalties to the dice pools based on circumstances. These lists are not all encompassing, and the Storyteller is encouraged to modify these circumstances as she sees fit.",
                "Other details such as duration, type of action required to activate and a description of the effects."
            ]
        },
        {
            "type": "heading",
            "level": 3,
            "text": "Touching the Target"
        },
        {
            "type": "paragraph",
            "text": "Some Transmutations require the Promethean to touch a target in order to be effective. Touching a target is an instant action that requires a roll of (Dexterity + Brawl) – target’s Defense. No damage is delivered by the touch itself, though the contact may deliver damage from a Transmutation. Armor does not usually apply against most rolls to touch the target, unless it is supernatural and provides a barrier between the target and the Promethean attempting to touch him."
        },
        {
            "type": "paragraph",
            "text": "If the Transmutation is reflexive, the Promethean may use it on the same turn that he touches the target, essentially activating it as he makes contact. An instant Transmutation requires the Promethean to first use an action to activate the power and then use his next action to actually touch the target. (He may grab the opponent and activate the power on the following turn instead, though the opponent can usually attempt to break the grip before the power is activated. See “Unarmed Combat” on p. 157 in the World of Darkness Rulebook.) Most effects can only be held for one turn before the channeled Pyros or flux must be passed to a target or lost. A successful activation of a Transmutation must always be accompanied by a successful touch to the target or followed immediately by a successful touch on the next turn, unless the Transmutation specifies otherwise."
        },
        {
            "type": "heading",
            "level": 3,
            "text": "Supernatural Conflict"
        },
        {
            "type": "paragraph",
            "text": "A Promethean’s Pilgrimage could bring her into contact with other bizarre denizens of the World of Darkness. Prometheans might have conflicts with vampires, mages or even stranger things. In this book, Transmutations are applied against mortal human beings and other Prometheans. In those cases, the rules operate as written. A mortal usually has little protection beyond his Resistance Attribute, while the Created gain a Resistance Attribute + Azoth in contested rolls."
        },
        {
            "type": "paragraph",
            "text": "When a Promethean encounters another supernatural being, that creature is likely to possess its own supernatural trait that adds to contested Resistance rolls. (This trait is usually Blood Potency for a vampire, Primal Urge for a werewolf and Gnosis for a mage.) Substitute Azoth for the other creature’s supernatural trait when the Created is resisting a supernatural power; substitute the other being’s supernatural trait for Azoth when it resists the effects of a Transmutation."
        }
    ],
    "Book": "PTC 117"
}

