                type: "paragraph",
                text: "At this level of self-mastery, the Promethean can alter the size and proportion of various parts of her body. She can stretch her legs to lengthen her stride. She can fit her entire body through the smallest of openings. She can even render her entire body pliant and rubbery so as to shrug off deadly blows."
