                        {
                            text: "Long Arms:",
                            italic: true
                        },
                        " The Promethean can stretch his arms to reach things that would otherwise be beyond his grasp. Both his arms lengthen by one foot per success. A Created with this alteration who engages in brawling combat gains a +1 Defense bonus, as his reach is much greater than that of his adversary. Alternatively, the Created can choose to lengthen only one of his arms so as to reach some object far beyond his normal grasp. In such a case, the affected arm lengthens by two feet per success, but the Created does not gain the Defense bonus in combat. In fact, he suffers a -1 penalty on any combat-related rolls while the alteration is in effect, due to the logistical problems of fighting with one arm much longer than the other. With an exceptional success, the Promethean’s arms grow by two feet per success (or three feet per success if just one limb is lengthened)."
