        "Notes": [
            {
                type: "heading",
                level: 2,
                text: "Metamorphosis and the Well-Dressed Promethean"
            },
            {
                type: "paragraph",
                text: "Procrustean Shape, along with many other Metamorphosis Transmutations, can be hard on the Created’s clothing, which seldom hold up to limbs that can stretch to many times their normal length. The problem of clothing is further exacerbated with higher-level Transmutations such as Shape of the Barghest or Guise of Proteus, both of which make significant changes to the Created’s musculature and/or Size. If the Promethean knows the Vulcanus Firebrand Transmutation, he can choose to brand his clothing. Apparel branded in this way is considered a part of the Promethean’s body for purposes of Metamorphosis Transmutations, and it can easily change with him. Any clothing to be affected must be relatively close fitting and must touch the Promethean’s skin in order to gain this benefit. Therefore, the Created’s pants, underwear, shirt, gloves, hat and socks can be made to change with him. Shoes and overcoats generally do not do so unless the Created is not wearing socks or a shirt so that those items can touch his skin directly."
            }
        ]
