        "Name": "Homunculus",
        "Class": "Metamorphosis",
        "Rank": "••••",
        "Prerequisites": "",
        "Cost": "● (●/●●)",
        "Dice Pool": "Intelligence + (Medicine or Occult)",
        "Description": "Eject a small secondary body and bounce your will between your two bodies",
