        "Name": "Chimera",
        "Class": "Metamorphosis",
        "Rank": "•••••",
        "Prerequisites": "Procrustean Shape",
        "Cost": "●",
        "Dice Pool": "Intelligence + Stamina",
        "Description": "Duplicate the shape of touched animals, or with the Mask Transmutation, people",
        "Book": "PTC 144",
        "UpperContent": [
            {
                type: "paragraph",
                text: "The Promethean is the perfect imposter, able to mimic any animal or creature, including its texture (fur, bone, etc.). In order to do so, however, he must touch the creature to be copied and activate this power. The chimera is a perfect copy of the form of the original specimen, but it has no trait increases or supernatural abilities associated with the specimen. Nor does it have any of that animal’s memories or training. The Created always retains his own Mental Attributes while in the form of the Chimera."
            }
        ],
        "FullPrerequisites": "Procrustean Shape (•••)",
        "FullCost": "1 Pyros",
        "FullDicePool": "Intelligence + Stamina",
        "Action": "Extended (5+ successes; one roll represents one turn of shapeshifting)",
        "BelowContent": [
            {
                type: "paragraph",
                text: "Once the Created touches a specimen and uses this power to assume its shape, the shape will remain in his mental library for a number of weeks equal to his Azoth. If he spends one experience point during this time, he can make his memory of the shape permanent."
            },
            {
                type: "paragraph",
                text: "The Created can assume the form of creatures much larger or smaller than himself. If he assumes the form of a larger creature, he must spend additional Pyros at a rate of one point per extra point of Size the desired form has. If the desired form is smaller, the excess quantity of the Created’s flesh sloughs off as he assumes the desired shape. In order to regain his former Size, the Created must return to the sloughed-off remains of his body and merge back into it. If those remains are somehow destroyed, the Promethean must devour enough food to enable him to change back — about 50 pounds per dot of Size to be recovered. Assuming the form of an animal with a very small Size is accordingly somewhat dangerous, as the smaller form loses a number of Health dots equal to the lost Size for the duration of the Transmutation. A Promethean can never assume the form of a creature below Size 1 or above Size 10."
            },
            {
                type: "paragraph",
                text: "The Created cannot assume the exact form of another person unless he also knows the Mask Deception Transmutation. If he does, he can copy a person perfectly by spending an additional Pyros point when the power is activated (and perhaps spending an experience point to add the person’s form permanently to his mental library). A Promethean without Mask can simply assume the form of a generic person who resembles the target. That is, the adopted form might have the same race, gender and approximate build as the target, but the Promethean would not be able to fool anyone who knew the target."
            },
            {
                type: "paragraph",
                text: "A Promethean cannot use Chimera to assume the functional form of a vampire. He lacks the magical power to animate a corpse in that manner. This Transmutation can only allow him to appear as a corpse that resembles the vampire (perfectly so, if Mask is used). If the character uses this power to mimic a werewolf, Chimera permits the Created to assume the form the creature was in when the Promethean touched it, but the Created gains no lupine shapeshifting abilities."
            },
            {
                type: "paragraph",
                text: "While the Promethean is in the new form, all of the normal advantages and disadvantages of Promethean existence apply to that form. As noted, the Created never gains any additional supernatural powers associated with the creature he copies."
            }
        ],
